'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='svoy-golos-v1';
let state={completed:{},sessions:[],last:null,pattern:null};
try{const saved=JSON.parse(localStorage.getItem(STORE)||'null');if(saved&&typeof saved==='object')state={...state,...saved};}catch{}
if(!state.completed||Array.isArray(state.completed)||typeof state.completed!=='object')state.completed={};
if(!Array.isArray(state.sessions))state.sessions=[];
let session=null,stepIndex=0,timer=null,remaining=0,deadline=0,auto=false,narrating=false,utterance=null,speechVersion=0,ctx=null,oscillators=new Set(),shift=0,seqTimer=null,seqStep=0,recordStream=null,recorder=null,recChunks=[],recordStart=0,recordTicker=null,recorderBusy=false,objectURLs=[],dbPromise=null,pendingFinish=null;
let pattern=Array.isArray(state.pattern)&&state.pattern.length===3&&state.pattern.every(r=>Array.isArray(r)&&r.length===8)?state.pattern:[[true,false,false,false,true,false,false,false],[false,false,true,false,false,false,true,false],[true,false,true,false,true,false,true,false]];
const formatTime=n=>`${Math.floor(Math.max(0,n)/60)}:${String(Math.max(0,n)%60).padStart(2,'0')}`;
const toast=text=>{const el=$('#toast');el.textContent=text;el.style.display='block';clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.style.display='none',4500);};
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Не удалось сохранить. Скачай резервную копию в «Прогрессе».');}}
function courseLessons(id){return LESSONS.filter(l=>l.course===id);}
function nextLesson(id){const all=courseLessons(id);return all.find(l=>!state.completed[l.id])||all[0];}
function courseProgress(id){const ls=courseLessons(id);return [ls.filter(l=>state.completed[l.id]).length,ls.length];}
function courseCard(c){const [done,total]=courseProgress(c.id);return `<a class="card course-card" href="#course/${c.id}"><div class="row between"><span class="num">${c.number}</span><span aria-hidden="true">→</span></div><h3>${c.name}</h3><p>${c.description}</p><footer><span>${total} занятий · ${c.duration}</span><span>${done}/${total}</span></footer><div class="bar" aria-label="Освоено ${done} из ${total}"><b style="width:${done/total*100}%"></b></div></a>`;}
function renderToday(){const last=LESSONS.find(l=>l.id===state.last?.id&&!state.completed[l.id]);const lesson=last||nextLesson('speech');const n=courseLessons(lesson.course).indexOf(lesson)+1;return `<div class="eyebrow">Речь · вокал · клавиши · музыка</div><h1>Голос, который<br>остаётся твоим.</h1><p class="intro">Читаешь. Пробуешь. Повторяешь.<br>По одному понятному шагу за раз.</p><div class="dashboard section"><section class="hero"><div class="hero-art" aria-hidden="true">${'<i></i>'.repeat(8)}</div><div class="eyebrow">${last?'Продолжить занятие':'Начать с простого'} · ${lesson.steps.reduce((s,x)=>s+x.seconds,0)/60} мин</div><h2>${lesson.title}</h2><p class="desc muted">${COURSES.find(c=>c.id===lesson.course).tag}. Занятие ${String(n).padStart(2,'0')} — без спешки и лишнего усилия.</p><a class="btn light" href="#lesson/${lesson.id}">${last?'Продолжить':'Начать занятие'} <span>→</span></a><p class="offline" style="color:#c2cfbe">Можно читать или слушать задания с паузами.</p></section><section class="section"><div class="section-heading"><h2>Четыре направления</h2><span class="tiny muted">В своём темпе</span></div><div class="grid">${COURSES.map(courseCard).join('')}</div></section></div><div class="note">За рулём — только слушать, без чтения, записи и нажатий в движении. Начни режим слушания до поездки. Клавиши и музыкальная мастерская — для практики на месте.</div><details><summary>Как пользоваться на телефоне</summary><p><a href="#install">Установка на телефон →</a></p><p class="muted">Открой меню браузера и выбери «Добавить на главный экран» или «Установить приложение», если такой пункт доступен. После первой загрузки уроки доступны офлайн. Озвучивание зависит от установленных голосов телефона; для офлайн-озвучивания может потребоваться русский голос. При сворачивании занятия приостанавливаются.</p><p id="offline-status" class="offline">Проверяем доступность офлайн…</p></details><div class="tools-row"><a class="btn secondary small" href="#install">Установить на телефон</a><a class="icon-btn" href="#method">Как устроено обучение</a></div>`;}
function renderCourse(id){const c=COURSES.find(x=>x.id===id);if(!c)return notFound();return `<a href="#courses" class="back">← Все направления</a><div class="eyebrow">Направление ${c.number}</div><h1>${c.name}</h1><p class="intro">${c.schedule}</p><ol class="lesson-list section">${courseLessons(id).map((l,i)=>`<li><a href="#lesson/${l.id}"><span class="badge">${state.completed[l.id]?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${l.title}</strong><small>${l.focus} · ${l.steps.reduce((s,x)=>s+x.seconds,0)/60} мин${l.home?' · на месте':''}</small></div><span class="arrow">→</span></a></li>`).join('')}</ol>`;}
function notFound(){return '<h1>Такого занятия нет</h1><a class="btn" href="#courses">Открыть курсы</a>';}
function renderSession(id){const lesson=LESSONS.find(l=>l.id===id);if(!lesson)return notFound();session=lesson;stepIndex=state.last?.id===id?Math.min(Math.max(Number(state.last.step)||0,0),lesson.steps.length-1):0;remaining=lesson.steps[stepIndex].seconds;state.last={id,step:stepIndex};save();return `<div class="reader"><a href="#course/${lesson.course}" class="back">← ${COURSES.find(c=>c.id===lesson.course).name}</a><div class="eyebrow">${lesson.focus} · ${lesson.home?'Практика на месте':'Читай или слушай'}</div><h1>${lesson.title}</h1>${!lesson.home?`<div class="mode"><label><input id="listen-mode" type="checkbox"> Слушать и повторять автоматически</label><small>Запусти до поездки. Озвучивание задания → пауза на упражнение → следующий шаг. При сворачивании — пауза.</small></div>`:''}<div id="step"></div><details><summary>Записать дубль и сравнить</summary><p class="tiny muted">Записывай только на месте. Запись хранится в этом браузере. Скачай её, чтобы сохранить отдельно.</p>${recordControls()}<div id="record-list"></div></details></div>`;}
function renderStep(){if(!session)return;const s=session.steps[stepIndex];const wrap=$('#step');if(!wrap)return;wrap.innerHTML=`<div class="row between stephead"><span class="eyebrow">Шаг ${stepIndex+1} из ${session.steps.length}</span><span class="tiny muted">${formatTime(s.seconds)}</span></div><div class="bar"><b style="width:${(stepIndex+1)/session.steps.length*100}%"></b></div><article class="card task-card section"><h2>${s.title}</h2><p class="task-text">${esc(s.instruction)}</p>${s.text?`<div class="sample">${esc(s.text)}</div>`:''}<div class="feedback">${esc(s.check)}</div>${s.notes?`<div class="tools-row"><button class="btn secondary small" id="example">${s.recall?'♪ Проверить пример':'♪ Послушать пример'}</button><button class="btn secondary small" id="lower" aria-label="Опустить пример на полутон">− Ниже</button><button class="btn secondary small" id="higher" aria-label="Поднять пример на полутон">+ Выше</button></div><p class="tiny muted" id="shift-label">Высота примера: ${shift>0?'+':''}${shift} полутонов</p>`:''}<div class="row between timerbar"><span class="timer" id="clock" role="timer">${formatTime(remaining)}</span><button id="timer-toggle" class="btn">${auto?'Слушать и начать':'Начать упражнение'}</button></div><div id="session-status" class="session-status" aria-live="polite">Таймер — ориентир. Можно повторить шаг в своём темпе.</div></article><div class="task-actions"><button class="btn secondary" id="prev-step" ${stepIndex===0?'disabled':''}>Назад</button><button class="btn" id="next-step">${stepIndex===session.steps.length-1?'Завершить занятие':'Сделал, дальше'} →</button></div><button class="icon-btn" id="speak-step">Озвучить задание</button>`;
$('#timer-toggle').onclick=toggleTimer;$('#prev-step').onclick=()=>changeStep(-1);$('#next-step').onclick=()=>changeStep(1);$('#speak-step').onclick=()=>speakStep(false);
if(s.notes){$('#example').onclick=()=>playExample(s.notes,session.course);$('#lower').onclick=()=>transpose(-1);$('#higher').onclick=()=>transpose(1);}
const mode=$('#listen-mode');if(mode){mode.checked=auto;mode.onchange=()=>{pauseSession();auto=mode.checked;renderStep();};}
}
function transpose(delta){shift=Math.max(-12,Math.min(12,shift+delta));$('#shift-label').textContent=`Высота примера: ${shift>0?'+':''}${shift} полутонов`;}
function status(text){if($('#session-status'))$('#session-status').textContent=text;}
function updateClock(){if($('#clock'))$('#clock').textContent=formatTime(remaining);}
function stopSpeech(){speechVersion++;if('speechSynthesis'in window)speechSynthesis.cancel();narrating=false;utterance=null;}
let wakeLock=null;
async function keepAwake(){try{if(auto&&navigator.wakeLock&&!wakeLock)wakeLock=await navigator.wakeLock.request('screen');}catch{}}
function releaseAwake(){if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null;}}
function pauseSession(){releaseAwake();clearInterval(timer);timer=null;stopSpeech();stopAudio(false);if($('#timer-toggle'))$('#timer-toggle').textContent=auto?'Продолжить слушать':'Продолжить';status('Пауза. Продолжи, когда будет удобно.');}
function beginCountdown(){if(!session)return;if(remaining<=0)remaining=session.steps[stepIndex].seconds;deadline=Date.now()+remaining*1000;$('#timer-toggle').textContent='Пауза';status('Выполняй упражнение. Между повторами отдыхай.');timer=setInterval(()=>{remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));updateClock();if(remaining===0){clearInterval(timer);timer=null;if(auto)changeStep(1,true);else{$('#timer-toggle').textContent='Повторить таймер';status('Время шага закончилось. Нажми «Сделал, дальше», когда будешь готов.');}}},250);}
function toggleTimer(){if(timer||narrating){pauseSession();return;}if(auto)speakStep(true);else beginCountdown();}
function speakStep(countAfter){if(!('speechSynthesis'in window)){toast('Озвучивание в этом браузере недоступно. Открой в Chrome или используй текст.');return;}pauseSession();const s=session.steps[stepIndex];const token=++speechVersion;const u=new SpeechSynthesisUtterance(`${s.title}. ${s.instruction} ${s.text||''} ${s.check}`);u.lang='ru-RU';u.rate=.9;const voice=speechSynthesis.getVoices().find(v=>v.lang.startsWith('ru'));if(voice)u.voice=voice;utterance=u;narrating=true;keepAwake();$('#timer-toggle').textContent='Пауза';status('Слушай задание. После него будет время для повтора.');u.onend=async()=>{if(token!==speechVersion)return;narrating=false;utterance=null;if(countAfter){if(s.notes&&!s.recall)await playExample(s.notes,session.course);if(token===speechVersion&&session)beginCountdown();}else{if($('#timer-toggle'))$('#timer-toggle').textContent='Начать упражнение';status('Задание озвучено. Можно начать упражнение.');}};u.onerror=()=>{if(token!==speechVersion)return;pauseSession();toast('Не удалось озвучить. Проверь русский голос в настройках синтеза речи телефона.');};speechSynthesis.speak(u);}
function changeStep(delta,fromAuto=false){pauseSession();const next=stepIndex+delta;if(next>=session.steps.length){finishSession(fromAuto);return;}stepIndex=Math.max(0,next);remaining=session.steps[stepIndex].seconds;state.last={id:session.id,step:stepIndex};save();renderStep();window.scrollTo({top:0,behavior:'instant'});if(fromAuto&&auto)speakStep(true);}
function finishSession(fromAuto){pendingFinish=session;state.last=null;save();if(fromAuto&&'speechSynthesis'in window){const u=new SpeechSynthesisUtterance('Занятие закончено. Оценить результат можно после остановки.');u.lang='ru-RU';speechSynthesis.speak(u);}$('#step').innerHTML=`<article class="card task-card section"><div class="eyebrow">Практика завершена</div><h2 style="margin-top:15px">Что получилось сегодня?</h2><p class="muted">Это твоя оценка ощущений. Приложение не выставляет оценку голосу по записи.</p><label>Насколько легко получилось? 1 — трудно, 5 — свободно.</label><div class="rating">${[1,2,3,4,5].map(n=>`<button type="button" data-rating="${n}" aria-pressed="false">${n}</button>`).join('')}</div><label for="finish-note">Одна мысль о занятии</label><textarea id="finish-note" maxlength="1000" placeholder="Например: стал меньше спешить на концах фраз"></textarea>${session.home?'<label class="row"><input type="checkbox" id="hands-done"> Я выполнил практическое задание руками</label>':''}<p class="tiny muted" style="margin-top:15px">«Сохранить занятие» добавит запись в историю. Урок можно повторять сколько угодно.</p><button class="btn wide" id="save-finish">Сохранить занятие</button></article>`;
let rating=null;document.querySelectorAll('[data-rating]').forEach(b=>b.onclick=()=>{rating=Number(b.dataset.rating);document.querySelectorAll('[data-rating]').forEach(x=>{x.classList.toggle('chosen',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});});$('#save-finish').onclick=()=>{const l=pendingFinish;if(!l)return;const practiced=!l.home||$('#hands-done').checked;const entry={id:l.id,at:new Date().toISOString(),rating,note:$('#finish-note').value.trim(),practiced};state.sessions.push(entry);if(practiced)state.completed[l.id]=entry.at;save();pendingFinish=null;session=null;location.hash='progress';toast(practiced?'Занятие сохранено':'Чтение сохранено. Практику можно выполнить позже.');};}
function recordControls(){return '<div class="tools-row"><button class="btn small" id="record-start">● Записать</button><button class="btn secondary small" id="record-stop" disabled>Остановить</button><span id="record-status" class="tiny muted" aria-live="polite"></span></div>';}
function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!window.indexedDB)return reject(new Error('Хранилище записей недоступно'));const req=indexedDB.open('svoy-golos-recordings',1);req.onupgradeneeded=()=>req.result.createObjectStore('records',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});return dbPromise;}
async function dbTask(mode,op){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('records',mode);const req=op(tx.objectStore('records'));let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Ошибка сохранения'));});}
function bindRecorder(){if(!$('#record-start'))return;$('#record-start').onclick=startRecording;$('#record-stop').onclick=stopRecording;listRecordings();}
async function startRecording(){if(recorderBusy){toast('Дождись сохранения текущего дубля.');return;}recorderBusy=true;try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw new Error('Запись недоступна. Используй Chrome и защищённое соединение.');await openDB();const lessonId=session?.id||'free';const title=session?.title||'Свободная запись';const startBtn=$('#record-start');startBtn.disabled=true;recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(!document.contains(startBtn)){recordStream.getTracks().forEach(t=>t.stop());recordStream=null;recorderBusy=false;return;}const type=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(t=>MediaRecorder.isTypeSupported(t));recorder=type?new MediaRecorder(recordStream,{mimeType:type}):new MediaRecorder(recordStream);recChunks=[];recordStart=Date.now();recorder.ondataavailable=e=>{if(e.data.size)recChunks.push(e.data);};recorder.onstop=async()=>{clearInterval(recordTicker);recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;const blob=new Blob(recChunks,{type:recorder.mimeType});const entry={id:Date.now()+'-'+Math.random().toString(36).slice(2,8),lessonId,title,at:new Date(recordStart).toISOString(),seconds:Math.round((Date.now()-recordStart)/1000),blob};let stored=false;try{await dbTask('readwrite',s=>s.put(entry));stored=true;toast('Дубль сохранён на этом устройстве.');}catch{const url=URL.createObjectURL(blob);objectURLs.push(url);const link=document.createElement('a');link.href=url;link.download='voice-recording.'+(blob.type.includes('mp4')?'m4a':'webm');link.textContent='Скачать запись, которую не удалось сохранить';link.className='btn';$('#record-list')?.prepend(link);toast('Хранилище заполнено. Скачай запись по кнопке.');}recorder=null;recorderBusy=false;if($('#record-start'))$('#record-start').disabled=false;if($('#record-stop'))$('#record-stop').disabled=true;if($('#record-status'))$('#record-status').textContent='Запись остановлена';if(stored)listRecordings();};recorder.start(1000);$('#record-stop').disabled=false;$('#record-status').textContent='Идёт запись · 0:00';recordTicker=setInterval(()=>{if($('#record-status'))$('#record-status').textContent='Идёт запись · '+formatTime(Math.floor((Date.now()-recordStart)/1000));if(Date.now()-recordStart>=300000)stopRecording();},500);}catch(e){recorderBusy=false;recordStream?.getTracks().forEach(t=>t.stop());recordStream=null;if($('#record-start'))$('#record-start').disabled=false;toast(e.message||'Разреши доступ к микрофону в настройках браузера.');}}
function stopRecording(){if(recorder?.state==='recording')recorder.stop();}
async function listRecordings(){const el=$('#record-list');if(!el)return;try{const records=await dbTask('readonly',s=>s.getAll());if(!document.contains(el))return;const filtered=records.filter(r=>!session||r.lessonId===session.id).sort((a,b)=>b.at.localeCompare(a.at));el.innerHTML=filtered.length?'':'<p class="tiny muted">Здесь появятся твои дубли. Автоматической оценки тембра нет.</p>';filtered.forEach(r=>{const div=document.createElement('div');div.className='recording';const url=URL.createObjectURL(r.blob);objectURLs.push(url);div.innerHTML=`<strong>${esc(r.title)}</strong><div class="tiny muted">${new Date(r.at).toLocaleString('ru-RU')} · ${formatTime(r.seconds)}</div><audio controls preload="none" src="${url}"></audio><div class="row"><a class="btn secondary small" href="${url}" download="voice-${r.at.slice(0,10)}-${r.id}.${r.blob.type.includes('mp4')?'m4a':'webm'}">Скачать</a><button class="icon-btn">Удалить</button></div>`;div.querySelector('button').onclick=async()=>{if(!confirm('Удалить этот дубль с устройства?'))return;await dbTask('readwrite',s=>s.delete(r.id));div.remove();URL.revokeObjectURL(url);};el.append(div);});}catch{el.textContent='Хранение записей недоступно в этом браузере.';}}
function audioContext(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx;}
function tone(midi,duration=.45,delay=0,volume=.14){const c=audioContext(),o=c.createOscillator(),g=c.createGain(),at=c.currentTime+delay;o.type='triangle';o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(volume,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(g).connect(c.destination);o.start(at);o.stop(at+duration+.02);oscillators.add(o);o.onended=()=>oscillators.delete(o);}
async function playExample(notes,course){try{const c=audioContext();await c.resume();const midi=course==='vocal'?notes.map(n=>48+n+shift):notes.map(n=>n+shift);midi.forEach((n,i)=>tone(n,.45,i*.6));return new Promise(resolve=>setTimeout(resolve,midi.length*600));}catch{toast('Не удалось включить звук. Проверь настройки браузера.');}}
function stopAudio(stopTimer=true){if(stopTimer){clearInterval(seqTimer);seqTimer=null;document.querySelectorAll('.beat.now').forEach(b=>b.classList.remove('now'));if($('#seq-play'))$('#seq-play').textContent='▶ Воспроизвести';if(metronome){clearInterval(metronome);metronome=null;if($('#metro'))$('#metro').textContent='Метроном';}}for(const o of oscillators){try{o.stop();}catch{}}oscillators.clear();}
const notesNames=['До','До♯','Ре','Ре♯','Ми','Фа','Фа♯','Соль','Соль♯','Ля','Ля♯','Си'];
function keyboard(){let html='';const whites=[0,2,4,5,7,9,11,12],blacks=[[1,1],[3,2],[6,4],[8,5],[10,6]];whites.forEach((n,i)=>html+=`<button class="key" data-note="${60+n}" style="left:${i*12.5}%;width:12.5%" aria-label="${notesNames[n%12]} ${n===12?5:4}">${notesNames[n%12]}${n===12?'5':''}</button>`);blacks.forEach(([n,pos])=>html+=`<button class="key black" data-note="${60+n}" style="left:${pos*12.5-4}%;width:8%" aria-label="${notesNames[n]} 4">${notesNames[n]}</button>`);return html;}
let metronome=null;
function renderTools(){return `<div class="eyebrow">Пробовать на месте</div><h1>От слов — к звуку.</h1><p class="intro">Маленькая мастерская для занятия. Клавиши отвечают звуком, записи помогают услышать себя.</p><div class="wide-grid"><div><section class="card toolcard"><h2>Клавиши под рукой</h2><p class="tiny muted">Октава До4–До5. Это звуковой ориентир; посадку и движения рук тренируй на настоящем инструменте.</p><div class="keywrap">${keyboard()}</div><div class="piano-label" id="played-note">Нажми клавишу, чтобы услышать ноту</div><div class="tools-row">${Object.keys(chords).map(c=>`<button class="btn secondary small" data-chord="${c}">${c}</button>`).join('')}</div><div class="divider"></div><div class="row"><label for="bpm">Темп BPM</label><input id="bpm" type="number" min="40" max="180" value="80" style="width:90px"><button class="btn secondary small" id="metro">Метроном</button></div><p class="tiny muted" style="margin-top:12px">1 такт = 4 доли. Восемь шагов бита — восьмые ноты.</p></section><section class="card toolcard"><h2>Повтори мелодию</h2><p class="muted">Слушай и повторяй на «му». Это упражнение на слух без автоматической оценки попадания.</p><div class="tools-row"><button class="btn small" id="ear-example">♪ Три ноты</button><button class="btn secondary small" id="ear-low">− Ниже</button><button class="btn secondary small" id="ear-high">+ Выше</button></div><p class="tiny muted" id="ear-shift">Высота: ${shift>0?'+':''}${shift} полутонов</p></section></div><div><section class="card toolcard"><h2>Первый бит</h2><p class="tiny muted">Восемь шагов. Нажми клетку, чтобы добавить или убрать удар. Сначала включи пример.</p><div id="sequencer"></div><div class="tools-row"><button class="btn small" id="seq-play">▶ Воспроизвести</button><button class="btn secondary small" id="seq-example">Пример бита</button></div><div class="tools-row"><button class="icon-btn" id="seq-save">Скачать проект</button><label class="icon-btn" style="margin:0;cursor:pointer">Открыть проект<input type="file" id="seq-import" accept="application/json,.json" class="import"></label></div><p class="tiny muted">JSON сохраняет темп и рисунок ударных. Это редактируемый эскиз, без экспорта аудио и многодорожечной записи.</p></section><section class="card toolcard"><h2>Мой голос</h2><p class="tiny muted">Запиши до 5 минут, прослушай и скачай дубль. Вся запись остаётся на устройстве.</p><details><summary>Контрольный текст</summary><p>${CONTROL_TEXT}</p></details>${recordControls()}<div id="record-list"></div></section></div></div>`;}
const chords={C:[60,64,67],Cm:[60,63,67],G:[55,59,62],Am:[57,60,64],F:[53,57,60],Dm:[50,53,57],E:[52,56,59]};
function bindTools(){document.querySelectorAll('[data-note]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();try{tone(Number(b.dataset.note));b.classList.add('playing');setTimeout(()=>b.classList.remove('playing'),300);$('#played-note').textContent=notesNames[b.dataset.note%12]+Math.floor(b.dataset.note/12-1);}catch{toast('Звук недоступен в этом браузере');}};b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();tone(Number(b.dataset.note));}};});document.querySelectorAll('[data-chord]').forEach(b=>b.onclick=()=>{chords[b.dataset.chord].forEach(n=>tone(n,1));$('#played-note').textContent=b.dataset.chord+' · '+chords[b.dataset.chord].map(n=>notesNames[n%12]).join(' — ');});$('#ear-example').onclick=()=>playExample([0,2,4,2,0],'vocal');const updateShift=d=>{shift=Math.max(-12,Math.min(12,shift+d));$('#ear-shift').textContent='Высота: '+(shift>0?'+':'')+shift+' полутонов';};$('#ear-low').onclick=()=>updateShift(-1);$('#ear-high').onclick=()=>updateShift(1);$('#metro').onclick=()=>{if(metronome){clearInterval(metronome);metronome=null;$('#metro').textContent='Метроном';return;}stopAudio();let beat=0;const tick=()=>tone(beat++%4===0?84:79,.04,0,.1);tick();metronome=setInterval(tick,60000/getBpm());$('#metro').textContent='Стоп метроном';};$('#bpm').onchange=()=>{getBpm();stopAudio();};renderSequencer();$('#seq-play').onclick=toggleSequence;$('#seq-example').onclick=()=>{pattern=[[true,false,false,false,true,false,false,false],[false,false,true,false,false,false,true,false],[true,false,true,false,true,false,true,false]];persistPattern();renderSequencer();};$('#seq-save').onclick=()=>download('svoy-golos-beat.json',{format:'svoy-golos-beat',version:1,bpm:getBpm(),pattern});$('#seq-import').onchange=importBeat;bindRecorder();}
function getBpm(){const el=$('#bpm');const bpm=Math.max(40,Math.min(180,Number(el?.value)||80));if(el)el.value=bpm;return bpm;}
function persistPattern(){state.pattern=pattern;save();}
function renderSequencer(){const el=$('#sequencer');if(!el)return;el.innerHTML=`<div class="seq"><small></small>${Array.from({length:8},(_,i)=>`<small style="text-align:center">${i+1}</small>`).join('')}${['Бочка','Хлопок','Хэт'].map((name,r)=>`<small>${name}</small>${pattern[r].map((on,c)=>`<button class="beat ${on?'on':''}" data-row="${r}" data-col="${c}" aria-label="${name}, шаг ${c+1}" aria-pressed="${on}"></button>`).join('')}`).join('')}</div>`;document.querySelectorAll('.beat').forEach(b=>b.onclick=()=>{const r=Number(b.dataset.row),c=Number(b.dataset.col);pattern[r][c]=!pattern[r][c];b.classList.toggle('on',pattern[r][c]);b.setAttribute('aria-pressed',String(pattern[r][c]));persistPattern();});}
function drum(row){const c=audioContext(),at=c.currentTime;if(row===0){const o=c.createOscillator(),g=c.createGain();o.frequency.setValueAtTime(140,at);o.frequency.exponentialRampToValueAtTime(40,at+.15);g.gain.setValueAtTime(.4,at);g.gain.exponentialRampToValueAtTime(.001,at+.2);o.connect(g).connect(c.destination);o.start();o.stop(at+.22);oscillators.add(o);o.onended=()=>oscillators.delete(o);}else{const length=Math.floor(c.sampleRate*(row===1?.12:.04)),buffer=c.createBuffer(1,length,c.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=(Math.random()*2-1)*(1-i/length);const src=c.createBufferSource(),filter=c.createBiquadFilter(),g=c.createGain();src.buffer=buffer;filter.type='highpass';filter.frequency.value=row===1?1200:7000;g.gain.value=row===1?.18:.12;src.connect(filter).connect(g).connect(c.destination);src.start();oscillators.add(src);src.onended=()=>oscillators.delete(src);}}
function toggleSequence(){if(seqTimer){stopAudio();return;}stopAudio();audioContext();seqStep=0;const tick=()=>{document.querySelectorAll('.beat').forEach(b=>b.classList.toggle('now',Number(b.dataset.col)===seqStep));pattern.forEach((r,i)=>{if(r[seqStep])drum(i);});seqStep=(seqStep+1)%8;};tick();seqTimer=setInterval(tick,60000/getBpm()/2);$('#seq-play').textContent='■ Остановить';}
async function importBeat(e){try{const file=e.target.files[0];if(!file)return;if(file.size>100000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='svoy-golos-beat'||!Array.isArray(d.pattern)||d.pattern.length!==3||!d.pattern.every(r=>Array.isArray(r)&&r.length===8&&r.every(v=>typeof v==='boolean'))||!Number.isFinite(d.bpm)||d.bpm<40||d.bpm>180)throw Error();stopAudio();pattern=d.pattern;$('#bpm').value=d.bpm;persistPattern();renderSequencer();toast('Проект открыт');}catch{toast('Не удалось открыть. Нужен проект бита, сохранённый в этом приложении.');}}
function renderProgress(){const count=Object.keys(state.completed).filter(id=>LESSONS.some(l=>l.id===id)).length;return `<div class="eyebrow">Без спешки и рекордов</div><h1>Слышать изменения.</h1><p class="intro">Сравнивай себя с собой. Повторять один урок — нормально.</p><div class="stats"><div class="stat"><b>${state.sessions.length}</b><span>занятий в истории</span></div><div class="stat"><b>${count}</b><span>уроков освоено</span></div><div class="stat"><b>${new Set(state.sessions.map(s=>s.at?.slice(0,10))).size}</b><span>дней практики</span></div></div><div class="grid">${COURSES.map(courseCard).join('')}</div><section class="section"><div class="section-heading"><h2>История практики</h2><span class="tiny muted">Личные наблюдения</span></div>${state.sessions.length?state.sessions.slice().reverse().slice(0,30).map(s=>`<article class="card" style="margin-bottom:10px"><div class="eyebrow">${new Date(s.at).toLocaleDateString('ru-RU')} · ${s.rating?'лёгкость '+s.rating+'/5':'без оценки'}${s.practiced===false?' · только чтение':''}</div><h3 style="margin-top:8px">${esc(LESSONS.find(l=>l.id===s.id)?.title||'Занятие')}</h3>${s.note?`<p class="muted" style="margin:0">${esc(s.note)}</p>`:''}</article>`).join(''):'<div class="card"><h3>Первый шаг ещё впереди</h3><p class="muted">После завершения занятия здесь появятся твоя оценка лёгкости и заметка.</p><a class="btn small" href="#lesson/speech-1">Начать с речи →</a></div>'}</section><section class="card section"><h2>Сохранить свой прогресс</h2><p class="muted">Прогресс и заметки хранятся в этом браузере. Резервная копия переносит их на другое устройство. Аудиозаписи скачиваются отдельно в практике.</p><div class="tools-row"><button class="btn small" id="export">Скачать копию</button><label class="btn secondary small" style="margin:0;cursor:pointer">Восстановить<input class="import" type="file" id="import-progress" accept=".json,application/json"></label></div></section>`;}
function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
async function importProgress(e){try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error();const d=JSON.parse(await file.text());if(d.format!=='svoy-golos-backup'||d.version!==1||!d.state||typeof d.state.completed!=='object'||Array.isArray(d.state.completed)||!Array.isArray(d.state.sessions))throw Error();const known=new Set(LESSONS.map(l=>l.id));if(!d.state.sessions.every(s=>s&&known.has(s.id)&&typeof s.at==='string'&&!isNaN(Date.parse(s.at))&&(s.rating===null||[1,2,3,4,5].includes(s.rating))&&typeof s.note==='string'&&s.note.length<=1000&&typeof s.practiced==='boolean'))throw Error();if(!confirm('Объединить резервную копию с текущим прогрессом? Записи голоса не изменятся.'))return;state.completed={...state.completed,...Object.fromEntries(Object.entries(d.state.completed).filter(([id,v])=>known.has(id)&&typeof v==='string'&&!isNaN(Date.parse(v))))};const entries=new Map([...state.sessions,...d.state.sessions].map(s=>[s.id+'|'+s.at,s]));state.sessions=[...entries.values()].sort((a,b)=>a.at.localeCompare(b.at));save();route();toast('Прогресс восстановлен');}catch{toast('Не удалось восстановить. Выбери резервную копию этого приложения.');}}
function cleanup(){pauseSession();stopAudio();stopRecording();document.querySelectorAll('audio').forEach(a=>a.pause());objectURLs.forEach(u=>URL.revokeObjectURL(u));objectURLs=[];session=null;auto=false;}
function route(){cleanup();const [page='today',id]=location.hash.replace(/^#\/?/,'').split('/');const app=$('#app');const navPage=['course','lesson'].includes(page)?'courses':page;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===navPage);if(a.dataset.nav===navPage)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});switch(page){case 'today':case '':app.innerHTML=renderToday();updateOffline();break;case 'courses':app.innerHTML='<div class="eyebrow">Один экран — одна задача</div><h1>Твой маршрут.</h1><p class="intro">Речь и вокал — короткими подходами. Клавиши и музыка — с практикой руками.</p><div class="grid section">'+COURSES.map(courseCard).join('')+'</div>';break;case 'course':app.innerHTML=renderCourse(id);break;case 'lesson':app.innerHTML=renderSession(id);renderStep();bindRecorder();break;case 'tools':app.innerHTML=renderTools();bindTools();break;case 'install':app.innerHTML=renderInstall();bindInstall();break;case 'method':app.innerHTML=renderMethod();break;case 'progress':app.innerHTML=renderProgress();$('#export').onclick=()=>download('svoy-golos-progress.json',{format:'svoy-golos-backup',version:1,state:{completed:state.completed,sessions:state.sessions}});$('#import-progress').onchange=importProgress;break;default:app.innerHTML=notFound();}window.scrollTo({top:0,behavior:'instant'});}
async function updateOffline(){const el=$('#offline-status');if(!el)return;try{const cache=await caches.open('svoy-golos-v2');const ready=await cache.match(new URL('app.js',location.href).href);if(document.contains(el))el.textContent=ready?'Уроки сохранены для офлайн-доступа. Русский голос для озвучивания настраивается на телефоне.':'Офлайн-копия ещё загружается. Пока нужна сеть.';}catch{el.textContent='Этот браузер не предоставил офлайн-хранилище. Нужна сеть.';}}

let installEvent=null;
const isStandalone=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
function renderInstall(){return `<a class="back" href="#today">← На главную</a><div class="eyebrow">Приложение на телефоне</div><h1>Один значок.<br>Все занятия.</h1><p class="intro">Открывай тренировку с главного экрана. После загрузки учебные тексты и звуковые примеры доступны без сети.</p><section class="card section"><h2>Установить приложение</h2><p id="install-status" class="muted"></p><button id="install-app" class="btn">Установить</button><div class="divider"></div><h3>Android · Chrome</h3><p>Открой опубликованную ссылку в обычном Chrome. В меню ⋮ выбери «Установить приложение» или «Добавить на главный экран». Название пункта зависит от версии браузера. Затем подтверди установку.</p><h3>iPhone</h3><p>Открой ссылку в Safari. Нажми «Поделиться» → «На экран Домой». Установочная кнопка внутри страницы может быть недоступна.</p><p class="tiny muted">Озвучивание использует голос телефона. Для работы без сети может понадобиться загруженный русский голос. При сворачивании тренировка ставится на паузу.</p></section><section class="card section"><h2>Если устанавливаешь из GitHub</h2><p>Сначала размести код через GitHub Pages. На телефоне нужно открыть адрес опубликованного приложения, а не страницу файлов репозитория и не скачанный HTML.</p><ol><li>Загрузи исходники в отдельный репозиторий.</li><li>В Settings → Pages выбери GitHub Actions.</li><li>В Actions запусти «Publish to GitHub Pages».</li><li>Дождись успешной публикации и открой выданную ссылку на телефоне.</li></ol><p class="tiny muted">На GitHub Free Pages доступен для публичных репозиториев. На опубликованной версии GitHub Pages нет входа через ChatGPT. Не добавляй аудиозаписи и личные заметки в репозиторий.</p></section><div class="note">Прогресс и записи принадлежат браузеру и адресу приложения. Перед переходом на другую ссылку сохрани резервную копию прогресса и скачай нужные дубли.</div>`;}
function bindInstall(){const b=$('#install-app'),p=$('#install-status');if(!b||!p)return;if(isStandalone()){b.hidden=true;p.textContent='Приложение уже открыто в отдельном окне.';return;}b.hidden=!installEvent;p.textContent=installEvent?'Браузер готов установить приложение.':'Если кнопка установки не появилась, используй меню браузера — инструкция ниже.';b.onclick=async()=>{const event=installEvent;if(!event)return;try{await event.prompt();const choice=await event.userChoice;installEvent=null;p.textContent=choice.outcome==='accepted'?'Установка запрошена. Подтверди её в браузере.':'Установку можно повторить через меню браузера.';b.hidden=true;}catch{toast('Открой меню браузера и выбери установку приложения.');}};}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e;bindInstall();});
window.addEventListener('appinstalled',()=>{installEvent=null;bindInstall();toast('Приложение установлено');});
function renderMethod(){return `<a class="back" href="#today">← На главную</a><div class="eyebrow">Принципы и источники</div><h1>Практика со смыслом.</h1><p class="intro">Сопоставление с профессиональными источниками, а не сертификация приложения. Ни одна из перечисленных организаций не проверяла и не одобряла этот тренажёр.</p><section class="card section"><h2>Речь и голос</h2><p>Обычная удобная громкость, отдых между повторами, отсутствие искусственного баса. Не перекрикивай шум и не тренируй голос через осиплость или усталость. Эти ориентиры согласуются с рекомендациями NIDCD по сохранению голоса.</p><p><a href="https://www.nidcd.nih.gov/health/taking-care-your-voice" target="_blank" rel="noopener noreferrer">NIDCD · Taking Care of Your Voice ↗</a></p><p class="tiny muted">Уроки не диагностируют голос и не заменяют работу со специалистом. Длительность 9 или 18 минут — настройка этого тренажёра, а не универсальная лечебная норма.</p></section><section class="card section"><h2>Слух и вокал</h2><p>Berklee объединяет слушание, внутреннее представление звука, пение и игру. В тренажёре есть звуковые примеры и этап «Представить и проверить»: сначала вспоминаешь и поёшь, затем сверяешься с образцом.</p><p><a href="https://college.berklee.edu/ear-training/ear-training-core" target="_blank" rel="noopener noreferrer">Berklee · Ear Training Core ↗</a></p><p class="tiny muted">Полная программа шире: сольфеджио, запись услышанного нотами, чтение нот и обратная связь. Автоматического анализа точности пения здесь пока нет.</p></section><section class="card section"><h2>Клавиши</h2><p>В инструментах ABRSM используются замедление и повтор трудных фрагментов. В этих занятиях тоже сначала осваивается небольшой рисунок, а затем он повторяется без подсказки. Чтение урока не отмечается как освоение практики на инструменте.</p><p><a href="https://www.abrsm.org/en-gb/apps-and-practice-tools" target="_blank" rel="noopener noreferrer">ABRSM · Apps and practice tools ↗</a></p><p class="tiny muted">Это начальная практика аккордов и музыкальных идей. Для полноценного фортепианного курса нужны техника, ноты, репертуар и проверка движений рук преподавателем.</p></section><section class="card section"><h2>Как оценивать прогресс</h2><p>Раз в неделю записывай один и тот же контрольный текст. Сравнивай ясность, темп и паузы, отмечай одну конкретную задачу на следующий раз. В вокале слушай направление и ровность мелодии. В клавишах проверь, можешь ли сыграть без подсказки.</p><p class="tiny muted">Оценка лёгкости в истории — личное наблюдение. Она не является профессиональной оценкой голоса. Пользовательские заметки и записи остаются на устройстве.</p></section>`;}

$('#sound-stop').onclick=()=>{pauseSession();stopAudio();document.querySelectorAll('audio').forEach(a=>a.pause());toast('Звук остановлен');};
window.addEventListener('hashchange',route);document.addEventListener('visibilitychange',()=>{if(document.hidden){pauseSession();stopAudio();stopRecording();}});window.addEventListener('pagehide',()=>{stopSpeech();stopAudio();stopRecording();});
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>updateOffline()).catch(()=>{});
route();
